from pathlib import Path
from collections import Counter
import datetime,hashlib,json,re,subprocess,sys,urllib.parse
root=Path.cwd();task=root/'tasks/ui-test-coverage-20261022';ev=task/'evidence';out=ev/'refinement';catalog=task/'test-cases.md'
hashfile=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
text=catalog.read_text();inventory=json.loads((ev/'case-inventory.json').read_text());sources=json.loads((ev/'source-manifest.json').read_text())
records={r['case_id']:r for r in (json.loads(l) for l in (out/'case-reviews.jsonl').read_text().splitlines() if l.strip())}
quality=json.loads((out/'quality-results.json').read_text());states={r['id']:r for r in quality['scenarios']};findings=quality['findings']
heads=list(re.finditer(r'^#### ([A-Z][A-Z0-9-]+)\s*$',text,re.M));ids=[m[1] for m in heads];errors=[]
old_ids=[r['id'] for r in inventory['cases']]
if ids!=old_ids:errors.append('Case identity or order changed')
if len(ids)!=521 or len(set(ids))!=521:errors.append('Expected 521 unique case IDs')
if set(ids)!=set(records) or set(ids)!=set(states):errors.append('Case journal or checker reconciliation differs')
assertion_counts=[]
for row in inventory['cases']:
 cid=row['id'];i=ids.index(cid);b=text[heads[i].start():heads[i+1].start() if i+1<len(ids) else len(text)]
 b=re.split(r'^### Group:|^## Execution binding',b,flags=re.M)[0]
 g=re.search(r'```gherkin\n(.*?)\n```',b,re.S)[1]
 if f'case-reviews.jsonl#L{records[cid]["metadata_line"]}' not in b:errors.append(cid+' review link mismatch')
 if 'Version: 2.' not in b:errors.append(cid+' lacks version2')
 if not all(re.search(r'^\s*'+k+r'\s+\S',g,re.M) for k in ('Given','When','Then')):errors.append(cid+' lacks complete clauses')
 if not re.search(r'^\s*@'+re.escape(cid)+r'\s*\n\s*Scenario:',g,re.M):errors.append(cid+' lacks scoped tag')
 count=0;kind=None
 for line in g.splitlines():
  m=re.match(r'^\s*(Given|When|Then|And|But|\*)\s+',line)
  if not m:continue
  if m[1] not in ('And','But','*'):kind=m[1]
  if kind=='Then':count+=1
 if count<1:errors.append(cid+' lacks assertions')
 if hashfile(catalog)!=quality.get('catalog_sha256',hashfile(catalog)):errors.append('Checker catalog hash mismatch')
 if hashlib.sha256(b.encode()).hexdigest()!=records[cid]['canonical_case_sha256']:errors.append(cid+' journal hash mismatch')
 if row['status']!='NOT_RUN' or row['actual_result'] is not None or row['execution_evidence'] is not None:errors.append(cid+' has unsupported execution result')
 row.update(definition_version=2,assertion_count=count,source_ids=records[cid]['source_refs'],quality_status=states[cid]['status'],automation_ready=False,quality_findings=sum(f['scenario_id']==cid for f in findings),refinement_review='refinement/case-reviews.jsonl',gherkin_evidence='refinement/gherkin-manifest.json')
 assertion_counts.append(count)
inventory['definition_version']=2;inventory['catalog_sha256']=hashfile(catalog);inventory['by_quality_status']=dict(Counter(s['status'] for s in states.values()))
(ev/'case-inventory.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2)+'\n')
for key,field in [('by_category','category'),('by_basis','basis'),('by_priority','priority'),('by_status','status')]:
 if dict(Counter(c[field] for c in inventory['cases']))!=inventory[key]:errors.append(key+' differs')
for s in sources['sources']:
 if hashfile(root/s['path'])!=s['sha256']:errors.append('Stale source '+s['evidence_id'])
for s in sources.get('retained_knowledge_source_identities',[]):
 if hashfile(root/s['path'])!=s['sha256']:errors.append('Stale knowledge identity '+s['path'])
links=0
for f in task.rglob('*.md'):
 for m in re.finditer(r'(?<!!)\[[^\]]*\]\((<[^>]+>|[^)\n]+)\)',f.read_text()):
  raw=m[1].strip('<>').split(' "')[0]
  if re.match(r'^[a-z]+://',raw):continue
  target,_,anchor=urllib.parse.unquote(raw).partition('#');q=(f.parent/target).resolve() if target else f.resolve();links+=1
  if not q.is_file():errors.append(str(f.relative_to(root))+': missing '+raw);continue
  if anchor:
   body=q.read_text(errors='replace')
   if re.fullmatch(r'L\d+(?:-L?\d+)?',anchor):
    if max(map(int,re.findall(r'\d+',anchor)))>len(body.splitlines()):errors.append('Invalid source line '+raw)
   elif q.suffix=='.md':
    headings=re.findall(r'^#{1,6}\s+(.+?)\s*#*$',body,re.M)
    anchors=[re.sub(r'[^\w\- ]','',h.replace('`','').lower()).replace(' ','-') for h in headings]+re.findall(r'<a\s+id="([^"]+)"',body)
    if anchor not in anchors:errors.append('Missing heading '+raw)
args=['.venv/bin/ai-sdlc','lint',str(task/'intake.md'),str(catalog)]
r=subprocess.run(args,capture_output=True,text=True)
try:lint=json.loads(r.stdout)
except ValueError:lint={'stdout':r.stdout,'stderr':r.stderr};errors.append('Lint output invalid')
if r.returncode:errors.append('Artifact lint failed')
results={'status':'PASSED' if not errors else 'FAILED','run_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':args,'exit_code':r.returncode,'artifact_lint':lint,'catalog_checks':{'case_count':len(ids),'unique_case_ids':len(set(ids)),'refined_case_count':len(records),'definition_version':2,'minimum_assertions_per_case':min(assertion_counts),'total_assertions':sum(assertion_counts),'resolved_local_links':links,'source_fingerprints':len(sources['sources']),'all_execution_status':'NOT_RUN','errors':errors},'quality_gate':{'status':quality['status'],'automation_ready':False,'by_status':inventory['by_quality_status'],'results':'quality-results.json','limits':'Document checks do not resolve missing UI evidence, business authority, or automation bindings.'},'document_hashes':{str(f.relative_to(task)):hashfile(f) for f in task.rglob('*.md')},'validation_script':{'source':Path(__file__).read_text(),'sha256':hashfile(Path(__file__))}}
(out/'document-checks.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps({k:v for k,v in results.items() if k not in ('validation_script','artifact_lint','document_hashes')},indent=2));sys.exit(bool(errors))
